package com.ragpipeline.config;import ai.djl.huggingface.tokenizers.HuggingFaceTokenizer;import ai.onnxruntime.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import java.nio.file.Paths;@Configuration public class OnnxConfig{@Value("${bge.m3.model-path}")String m3;@Value("${bge.m3.tokenizer-path}")String m3t;@Value("${bge.reranker.model-path}")String reranker;@Value("${bge.reranker.tokenizer-path}")String rerankert;@Bean OrtEnvironment ortEnvironment(){return OrtEnvironment.getEnvironment();}@Bean("bgeM3Session")OrtSession m3(OrtEnvironment e)throws OrtException{return e.createSession(m3,new OrtSession.SessionOptions());}@Bean("bgeRerankerSession")OrtSession reranker(OrtEnvironment e)throws OrtException{return e.createSession(reranker,new OrtSession.SessionOptions());}@Bean("bgeM3Tokenizer")HuggingFaceTokenizer m3t()throws Exception{return HuggingFaceTokenizer.newInstance(Paths.get(m3t));}@Bean("bgeRerankerTokenizer")HuggingFaceTokenizer rt()throws Exception{return HuggingFaceTokenizer.newInstance(Paths.get(rerankert));}}
